 for(int I=0;I<400;I++){W->Step(.1f);FurthestX=FMath::Max(FurthestX,float(Trader->Pos.X));}float FirstWindow=W->Players[0].Resources.Z-Wealth;Run(60);
 Check(TEXT("galavant.public_route_moves_between_laborers_and_pays_repeatedly"),Trader->TradeRoute.Num()==2&&Trader->Order==TEXT("galavant")&&FurthestX>58&&FirstWindow>=4&&W->Players[0].Resources.Z-Wealth>=FirstWindow+4);
 Reset();Worker=Spawn(TEXT("industrious_laborer"),{42,40});Trader=Spawn(TEXT("trader_in_precious_things"),{40,40});auto Overlap=Spawn(TEXT("trader_in_precious_things"),{40,41});W->Command(C,TEXT("galavant"),{Trader->Id},Trader->Pos,0,TEXT(""));W->Command(C,TEXT("galavant"),{Overlap->Id},Overlap->Pos,0,TEXT(""));Wealth=W->Players[0].Resources.Z;Run(1);Check(TEXT("galavant.overlapping_traders_share_laborer_cooldown"),FMath::IsNearlyEqual(float(W->Players[0].Resources.Z-Wealth),2.f,.001f));Run(28);Check(TEXT("galavant.shared_cooldown_prevents_early_repeat"),FMath::IsNearlyEqual(float(W->Players[0].Resources.Z-Wealth),2.f,.001f));Run(2);Check(TEXT("galavant.shared_cooldown_allows_later_repeat"),FMath::IsNearlyEqual(float(W->Players[0].Resources.Z-Wealth),4.f,.001f));

 Reset();HQ=Spawn(TEXT("seat_of_the_people"),{20,20});auto Market=Spawn(TEXT("place_of_trade"),{35,60});Worker=Spawn(TEXT("industrious_laborer"),{39,60});Worker2=Spawn(TEXT("industrious_laborer"),{58,60});
 W->Command(C,TEXT("market_galavant"),{Market->Id},Market->Pos,Market->Id,TEXT(""));W->Command(C,TEXT("market_galavant"),{Market->Id},Worker2->Pos,Worker2->Id,TEXT(""),true);W->Command(C,TEXT("train"),{Market->Id},Market->Pos,0,TEXT("trader_in_precious_things"));Run(35);Trader=nullptr;for(auto& KV:W->Entities)if(W->D(*KV.Value).Kind==TEXT("trader"))Trader=KV.Value.Get();
