 Check(TEXT("raid.direct_laborer_cargo_is_conserved_before_dropoff"),Sum(Band->Cargo)>0&&FMath::IsNearlyEqual(float(Sum(Band->Cargo)+Sum(Victim->Cargo)),10.f,.001f)&&W->Players[1].Resources==VictimStock&&W->Players[0].Resources==ThiefStock&&Victim->FoodCredit<=Victim->Cargo.X+.001f&&Band->FoodCredit==0);
