 Check(TEXT("raid_move.acquires_loaded_enemy_laborer_then_delivers"),Victim->Cargo.IsNearlyZero(.001f)&&W->Players[0].Resources.Equals(ThiefStock+FVector(0,8,0),.001f)&&W->Players[1].Resources==VictimStock);

 Reset(TEXT("gadianton"));HQ=Spawn(TEXT("seat_of_the_people"),{20,20});Store=Spawn(TEXT("storehouse_of_provisions"),{30,40});Victim=Spawn(TEXT("industrious_laborer"),{43,40},1);Victim->Cargo=FVector(4,3,3);Band=Spawn(TEXT("gadianton_robber"),{41,40});W->Players[0].Upgrades.Add(TEXT("gadianton_storehouse_raid_yield"));Band->Cargo=FVector(W->CarryCapacity(*Band)-1,0,0);float InitialCargo=Sum(Band->Cargo);VictimStock=W->Players[1].Resources;W->Command(C,TEXT("raid"),{Band->Id},Victim->Pos,Victim->Id,TEXT(""));Run(4);float VictimDebit=10-Sum(Victim->Cargo),BonusYield=(W->CarryCapacity(*Band)-InitialCargo);Check(TEXT("raid.laborer_theft_capacity_and_explicit_bonus_preserve_base_debit"),FMath::IsNearlyEqual(float(VictimDebit*1.2f),BonusYield,.001f)&&VictimDebit>0&&Sum(Band->Cargo)<=W->CarryCapacity(*Band)+.001f&&W->Players[1].Resources==VictimStock);

 Reset(TEXT("gadianton"));HQ=Spawn(TEXT("seat_of_the_people"),{20,20});Store=Spawn(TEXT("storehouse_of_provisions"),{30,40});auto EnemyStore=Spawn(TEXT("storehouse_of_provisions"),{48,40},1);
 W->Command(C,TEXT("storehouse_raid"),{Store->Id},EnemyStore->Pos,EnemyStore->Id,TEXT(""));W->Command(C,TEXT("train"),{Store->Id},Store->Pos,0,TEXT("gadianton_robber"));Run(45);Band=nullptr;for(auto& KV:W->Entities)if(W->D(*KV.Value).Id==TEXT("gadianton_robber"))Band=KV.Value.Get();
 Check(TEXT("storehouse.public_raid_route_is_inherited_by_trained_robber"),Store->bRaidRallySet&&Band&&Band->TradeB==Store->Id&&Band->RaidSource==EnemyStore->Id);ThiefStock=W->Players[0].Resources;VictimStock=W->Players[1].Resources;Run(70);
