 auto Cement=Spawn(TEXT("cement_tower"),{60,60},0,3);Cement->HP-=30;float Maximum=Cement->MaxHP,HP=Cement->HP;Curelom->Pos={65,60};FVector Before=W->Players[0].Resources;W->Command(C,TEXT("context"),{Curelom->Id},Cement->Pos,Cement->Id,TEXT(""));Run(5);
 Check(TEXT("construction.lower_beast_repairs_completed_cement_without_tier_or_hp_rescale"),Cement->HP>HP&&Cement->MaxHP==Maximum&&Cement->Tier==3&&W->Players[0].Resources.Y<Before.Y);

 Reset(TEXT("gadianton"));Worker=Spawn(TEXT("industrious_laborer"),{40,40});auto Tree=Spawn(TEXT("tree"),{44,40},-1);W->Command(C,TEXT("gather"),{Worker->Id},Tree->Pos,Tree->Id,TEXT(""));Worker->Pos=W->WorkPosition(*Worker,*Tree);W->Economy(*Worker,1);Check(TEXT("gadianton.gathering_is_thirty_five_percent_of_ordinary_rate"),FMath::IsNearlyEqual(float(Worker->Cargo.Y),.7f*.35f,.001f));
 HQ=Spawn(TEXT("seat_of_the_people"),{60,40});auto Encampment=Spawn(TEXT("encampment_of_war"),{80,40});W->Time=6;Check(TEXT("gadianton.quiet_completed_hq_and_encampment_are_concealed"),W->IsStealthed(*HQ)&&W->IsStealthed(*Encampment));auto Enemy=Spawn(TEXT("bowman"),{67,40},1);Check(TEXT("gadianton.hidden_hq_requires_detector_even_with_live_sight"),!W->CanSee(1,*HQ));W->Damage(*HQ,*Enemy,2);Check(TEXT("gadianton.damage_reveals_hidden_building_for_five_seconds"),!W->IsStealthed(*HQ)&&W->CanSee(1,*HQ));W->Time+=5.1f;Check(TEXT("gadianton.building_concealment_recovers_after_damage"),W->IsStealthed(*HQ));Spawn(TEXT("tower_of_watchmen"),{65,44},1);Check(TEXT("gadianton.tower_detects_concealed_hq_in_line_of_sight"),W->CanSee(1,*HQ));

