 Worker=Spawn(TEXT("industrious_laborer"),{30,30});Before=W->Players[0].Resources;W->Command(C,TEXT("build"),{Worker->Id},{55,55},0,TEXT("temple_of_the_land"));Check(TEXT("great_spacious.age_three_placement_is_rejected_without_charge"),Count(TEXT("temple_of_the_land"))==0&&W->Players[0].Resources==Before);
